CREATE FUNCTION public.validate_noa_trip_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.requested_by IS DISTINCT FROM OLD.requested_by OR NEW.destination IS DISTINCT FROM OLD.destination OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Trip request fields cannot change'; END IF; IF OLD.driver_id IS NOT NULL AND NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN RAISE EXCEPTION 'Driver cannot change'; END IF; IF OLD.status IN ('stopped','declined') THEN RAISE EXCEPTION 'Trip already closed'; END IF; IF NEW.status='sharing' AND (NEW.consented_at IS NULL OR NEW.driver_id IS NULL) THEN RAISE EXCEPTION 'Driver consent required'; END IF; IF (NEW.latitude IS DISTINCT FROM OLD.latitude OR NEW.longitude IS DISTINCT FROM OLD.longitude) AND (OLD.status!='sharing' OR NEW.status!='sharing' OR OLD.consented_at IS NULL) THEN RAISE EXCEPTION 'Consent required before location update'; END IF; RETURN NEW; END $$;
CREATE TRIGGER noa_trip_consent_boundary BEFORE UPDATE ON public.noa_trips FOR EACH ROW EXECUTE FUNCTION public.validate_noa_trip_change();
ALTER PUBLICATION supabase_realtime ADD TABLE public.noa_trips;